-- =====================================================================
-- SmartBuy : schéma Oracle (Oracle Database 19c, utilisateur SMARTBUY)
-- 11 tables. Instructions simples séparées par ";" (pas de bloc PL/SQL)
-- pour pouvoir être exécutées par Spring (ResourceDatabasePopulator)
-- ou à la main dans SQL Developer (F5 = « Exécuter le script »).
--
-- Conventions (voir docs/04-architecture-et-donnees.md §4.4) :
--   * identifiants : NUMBER GENERATED BY DEFAULT AS IDENTITY
--   * montants     : NUMBER(12,3)  (dinar tunisien = 3 décimales)
--   * booléens     : CHAR(1) 'O' / 'N' + CHECK
--   * énumérations : VARCHAR2 + CHECK
-- =====================================================================

-- ---------------------------------------------------------------------
-- UTILISATEUR : compte de l'application
-- ---------------------------------------------------------------------
CREATE TABLE utilisateur (
    id                  NUMBER GENERATED BY DEFAULT AS IDENTITY,
    nom                 VARCHAR2(100)  NOT NULL,
    email               VARCHAR2(150)  NOT NULL,
    mot_de_passe_hache  VARCHAR2(100)  NOT NULL,
    role                VARCHAR2(10)   DEFAULT 'USER' NOT NULL,
    devise              VARCHAR2(3)    DEFAULT 'TND'  NOT NULL,
    revenu_mensuel      NUMBER(12,3),
    date_creation       TIMESTAMP      DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_utilisateur PRIMARY KEY (id),
    CONSTRAINT uq_utilisateur_email UNIQUE (email),
    CONSTRAINT ck_utilisateur_role CHECK (role IN ('USER', 'ADMIN')),
    CONSTRAINT ck_utilisateur_revenu CHECK (revenu_mensuel IS NULL OR revenu_mensuel >= 0)
);

-- ---------------------------------------------------------------------
-- CATEGORIE : catégorie de dépense ou de revenu
-- utilisateur_id NULL = catégorie par défaut (commune à tous)
-- ---------------------------------------------------------------------
CREATE TABLE categorie (
    id              NUMBER GENERATED BY DEFAULT AS IDENTITY,
    nom             VARCHAR2(60)  NOT NULL,
    type            VARCHAR2(10)  NOT NULL,
    icone           VARCHAR2(50),
    utilisateur_id  NUMBER,
    CONSTRAINT pk_categorie PRIMARY KEY (id),
    CONSTRAINT ck_categorie_type CHECK (type IN ('DEPENSE', 'REVENU')),
    CONSTRAINT fk_categorie_utilisateur FOREIGN KEY (utilisateur_id)
        REFERENCES utilisateur (id) ON DELETE CASCADE
);

-- ---------------------------------------------------------------------
-- MAGASIN : point de vente
-- ---------------------------------------------------------------------
CREATE TABLE magasin (
    id        NUMBER GENERATED BY DEFAULT AS IDENTITY,
    nom       VARCHAR2(100) NOT NULL,
    enseigne  VARCHAR2(60)  NOT NULL,
    adresse   VARCHAR2(200),
    ville     VARCHAR2(60),
    CONSTRAINT pk_magasin PRIMARY KEY (id)
);

-- ---------------------------------------------------------------------
-- CATEGORIE_PRODUIT : rayon (Produits laitiers, Boissons...)
-- ---------------------------------------------------------------------
CREATE TABLE categorie_produit (
    id   NUMBER GENERATED BY DEFAULT AS IDENTITY,
    nom  VARCHAR2(60) NOT NULL,
    CONSTRAINT pk_categorie_produit PRIMARY KEY (id),
    CONSTRAINT uq_categorie_produit_nom UNIQUE (nom)
);

-- ---------------------------------------------------------------------
-- PRODUIT : article du catalogue
-- ---------------------------------------------------------------------
CREATE TABLE produit (
    id                    NUMBER GENERATED BY DEFAULT AS IDENTITY,
    nom                   VARCHAR2(150) NOT NULL,
    marque                VARCHAR2(60),
    code_barres           VARCHAR2(20),
    unite                 VARCHAR2(10)  DEFAULT 'pièce' NOT NULL,
    categorie_produit_id  NUMBER        NOT NULL,
    image_url             VARCHAR2(500),
    CONSTRAINT pk_produit PRIMARY KEY (id),
    CONSTRAINT uq_produit_code_barres UNIQUE (code_barres),
    CONSTRAINT fk_produit_categorie FOREIGN KEY (categorie_produit_id)
        REFERENCES categorie_produit (id)
);

-- ---------------------------------------------------------------------
-- OPERATION : un revenu ou une dépense
-- (et non TRANSACTION, qui est un mot-clé SQL)
-- ---------------------------------------------------------------------
CREATE TABLE operation (
    id              NUMBER GENERATED BY DEFAULT AS IDENTITY,
    utilisateur_id  NUMBER        NOT NULL,
    categorie_id    NUMBER        NOT NULL,
    type            VARCHAR2(10)  NOT NULL,
    montant         NUMBER(12,3)  NOT NULL,
    date_operation  DATE          NOT NULL,
    note            VARCHAR2(255),
    magasin_id      NUMBER,
    recurrente      CHAR(1)       DEFAULT 'N' NOT NULL,
    economie        NUMBER(12,3)  DEFAULT 0   NOT NULL,
    CONSTRAINT pk_operation PRIMARY KEY (id),
    CONSTRAINT ck_operation_type CHECK (type IN ('DEPENSE', 'REVENU')),
    CONSTRAINT ck_operation_montant CHECK (montant > 0),
    CONSTRAINT ck_operation_recurrente CHECK (recurrente IN ('O', 'N')),
    CONSTRAINT ck_operation_economie CHECK (economie >= 0),
    CONSTRAINT fk_operation_utilisateur FOREIGN KEY (utilisateur_id)
        REFERENCES utilisateur (id) ON DELETE CASCADE,
    CONSTRAINT fk_operation_categorie FOREIGN KEY (categorie_id)
        REFERENCES categorie (id),
    CONSTRAINT fk_operation_magasin FOREIGN KEY (magasin_id)
        REFERENCES magasin (id) ON DELETE SET NULL
);

-- ---------------------------------------------------------------------
-- BUDGET : plafond mensuel (categorie_id NULL = budget global)
-- La contrainte UNIQUE empêche deux budgets pour la même catégorie et le même mois.
-- ---------------------------------------------------------------------
CREATE TABLE budget (
    id               NUMBER GENERATED BY DEFAULT AS IDENTITY,
    utilisateur_id   NUMBER        NOT NULL,
    categorie_id     NUMBER,
    mois             VARCHAR2(7)   NOT NULL,
    montant_plafond  NUMBER(12,3)  NOT NULL,
    CONSTRAINT pk_budget PRIMARY KEY (id),
    CONSTRAINT ck_budget_mois CHECK (REGEXP_LIKE(mois, '^[0-9]{4}-(0[1-9]|1[0-2])$')),
    CONSTRAINT ck_budget_plafond CHECK (montant_plafond > 0),
    CONSTRAINT uq_budget UNIQUE (utilisateur_id, categorie_id, mois),
    CONSTRAINT fk_budget_utilisateur FOREIGN KEY (utilisateur_id)
        REFERENCES utilisateur (id) ON DELETE CASCADE,
    CONSTRAINT fk_budget_categorie FOREIGN KEY (categorie_id)
        REFERENCES categorie (id) ON DELETE CASCADE
);

-- ---------------------------------------------------------------------
-- PRIX : prix d'un produit dans un magasin à une date
-- Le « prix actuel » = dernier prix VALIDE pour (produit, magasin).
-- ---------------------------------------------------------------------
CREATE TABLE prix (
    id           NUMBER GENERATED BY DEFAULT AS IDENTITY,
    produit_id   NUMBER        NOT NULL,
    magasin_id   NUMBER        NOT NULL,
    montant      NUMBER(12,3)  NOT NULL,
    date_releve  DATE          NOT NULL,
    source       VARCHAR2(12)  DEFAULT 'ADMIN'  NOT NULL,
    statut       VARCHAR2(12)  DEFAULT 'VALIDE' NOT NULL,
    propose_par  NUMBER,
    CONSTRAINT pk_prix PRIMARY KEY (id),
    CONSTRAINT ck_prix_montant CHECK (montant > 0),
    CONSTRAINT ck_prix_source CHECK (source IN ('ADMIN', 'UTILISATEUR')),
    CONSTRAINT ck_prix_statut CHECK (statut IN ('VALIDE', 'EN_ATTENTE', 'REJETE')),
    CONSTRAINT fk_prix_produit FOREIGN KEY (produit_id)
        REFERENCES produit (id) ON DELETE CASCADE,
    CONSTRAINT fk_prix_magasin FOREIGN KEY (magasin_id)
        REFERENCES magasin (id) ON DELETE CASCADE,
    CONSTRAINT fk_prix_utilisateur FOREIGN KEY (propose_par)
        REFERENCES utilisateur (id) ON DELETE SET NULL
);

-- ---------------------------------------------------------------------
-- LISTE_COURSES : liste préparée par l'utilisateur
-- ---------------------------------------------------------------------
CREATE TABLE liste_courses (
    id              NUMBER GENERATED BY DEFAULT AS IDENTITY,
    utilisateur_id  NUMBER        NOT NULL,
    nom             VARCHAR2(100) NOT NULL,
    date_creation   DATE          DEFAULT SYSDATE NOT NULL,
    statut          VARCHAR2(10)  DEFAULT 'EN_COURS' NOT NULL,
    CONSTRAINT pk_liste_courses PRIMARY KEY (id),
    CONSTRAINT ck_liste_statut CHECK (statut IN ('EN_COURS', 'ACHETEE')),
    CONSTRAINT fk_liste_utilisateur FOREIGN KEY (utilisateur_id)
        REFERENCES utilisateur (id) ON DELETE CASCADE
);

-- ---------------------------------------------------------------------
-- LIGNE_LISTE : un produit (et sa quantité) dans une liste
-- ---------------------------------------------------------------------
CREATE TABLE ligne_liste (
    id          NUMBER GENERATED BY DEFAULT AS IDENTITY,
    liste_id    NUMBER     NOT NULL,
    produit_id  NUMBER     NOT NULL,
    quantite    NUMBER(6)  NOT NULL,
    CONSTRAINT pk_ligne_liste PRIMARY KEY (id),
    CONSTRAINT ck_ligne_quantite CHECK (quantite > 0),
    CONSTRAINT uq_ligne_liste UNIQUE (liste_id, produit_id),
    CONSTRAINT fk_ligne_liste FOREIGN KEY (liste_id)
        REFERENCES liste_courses (id) ON DELETE CASCADE,
    CONSTRAINT fk_ligne_produit FOREIGN KEY (produit_id)
        REFERENCES produit (id) ON DELETE CASCADE
);

-- ---------------------------------------------------------------------
-- ALERTE : notification envoyée à l'utilisateur
-- budget_id permet de ne créer qu'une alerte par seuil et par budget (BUD-11).
-- ---------------------------------------------------------------------
CREATE TABLE alerte (
    id              NUMBER GENERATED BY DEFAULT AS IDENTITY,
    utilisateur_id  NUMBER        NOT NULL,
    type            VARCHAR2(12)  NOT NULL,
    message         VARCHAR2(255) NOT NULL,
    date_alerte     TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,
    lue             CHAR(1)       DEFAULT 'N' NOT NULL,
    budget_id       NUMBER,
    CONSTRAINT pk_alerte PRIMARY KEY (id),
    CONSTRAINT ck_alerte_type CHECK (type IN ('BUDGET_80', 'BUDGET_100', 'BAISSE_PRIX')),
    CONSTRAINT ck_alerte_lue CHECK (lue IN ('O', 'N')),
    CONSTRAINT fk_alerte_utilisateur FOREIGN KEY (utilisateur_id)
        REFERENCES utilisateur (id) ON DELETE CASCADE,
    CONSTRAINT fk_alerte_budget FOREIGN KEY (budget_id)
        REFERENCES budget (id) ON DELETE SET NULL
);

-- ---------------------------------------------------------------------
-- Index de recherche (NF-05, NF-06)
-- (les clés primaires et les contraintes UNIQUE ont déjà leur index)
-- ---------------------------------------------------------------------
CREATE INDEX ix_produit_nom ON produit (nom);
CREATE INDEX ix_prix_produit_magasin_date ON prix (produit_id, magasin_id, date_releve);
CREATE INDEX ix_operation_utilisateur_date ON operation (utilisateur_id, date_operation);
CREATE INDEX ix_budget_utilisateur_mois ON budget (utilisateur_id, mois);
CREATE INDEX ix_alerte_utilisateur ON alerte (utilisateur_id, date_alerte);
CREATE INDEX ix_categorie_utilisateur ON categorie (utilisateur_id);
CREATE INDEX ix_liste_utilisateur ON liste_courses (utilisateur_id);
